impl KindProof for KindAdmitted {
    type Missing<M> = Never;
    type Evidence = CanonicalLanguage;
    fn admit<'tree>(
        evidence: &CanonicalLanguage,
        node: tree_sitter::Node<'tree>,
    ) -> Result<tree_sitter::Node<'tree>, GrammarBindingError> {
        if *node.language() == evidence.compiled.language {
            Ok(node)
        } else {
            Err(GrammarBindingError::ForeignLanguage)
        }
    }
    fn missing<M>(_: M) -> Result<NarrowedMissing<Self, M>, MissingRefuted> {
        Err(MissingRefuted)
    }
    fn missing_as_ref<M>(missing: &Never) -> Never {
        match *missing {}
    }
    fn map_missing<M, N>(missing: Never, _: impl FnOnce(M) -> N) -> Never {
        match missing {}
    }
    fn try_map_missing<M, N, E>(
        missing: Never,
        _: impl FnOnce(M) -> Result<N, E>,
    ) -> Result<Never, E> {
        match missing {}
    }
    fn missing_payload<M>(missing: Never) -> M {
        match missing {}
    }
}
