trait RangeAdmissionSeal {}
/// Generated structural conversion, sealed against caller-supplied projections.
///
/// The admission context has no public constructor: only source-owned children
/// can enter this transition. The output retains every selected recovery state.
///
/// An external projection cannot claim canonical association:
/// ```ignore
/// use tree_sitter_node_types::runtime::{AdmitRanges, RangeAdmission, SourceBindingError};
/// struct Forged;
/// // The sealing supertrait is private, so `Forged` cannot satisfy it.
/// // Expected: E0277, "the trait bound `Forged: RangeAdmissionSeal` is not
/// // satisfied" (stable rustdoc does not check the code; see the module docs).
/// impl<'tree, 'source> AdmitRanges<'tree, 'source> for Forged {
///     type Admitted = ();
///     fn admit_ranges_in(self, _: &mut RangeAdmission<'tree, 'source>) -> Result<(), SourceBindingError> {
///         Ok(())
///     }
/// }
/// ```
#[allow(private_bounds)]
pub trait AdmitRanges<'tree, 'source>: RangeAdmissionSeal {
    /// The same selected structure with checked, readable leaves.
    type Admitted;
    /// Generated conversion; callers use `SourceChildren::admit_ranges`.
    /// # Errors
    /// Rejects unreadable selected ranges without returning a partial carrier.
    fn admit_ranges_in(
        self,
        context: &mut RangeAdmission<'tree, 'source>,
    ) -> Result<Self::Admitted, SourceBindingError>;
}
/// Unforgeable context for an already source-associated extraction carrier.
///
/// A readable parent alone cannot authorize caller-supplied child nodes:
/// ```ignore
/// use tree_sitter_node_types::runtime::{RangeAdmission, SourceSlice};
/// fn forge<'tree, 'source>(parent: SourceSlice<'tree, 'source>) -> RangeAdmission<'tree, 'source> {
///     // The fields are private. Expected: E0451, "field `parent` of struct
///     // `RangeAdmission` is private".
///     RangeAdmission { parent, checked_ranges: 0 }
/// }
/// ```
pub struct RangeAdmission<'tree, 'source> {
    parent: SourceSlice<'tree, 'source>,
    checked_ranges: usize,
}
impl<'tree, 'source> RangeAdmission<'tree, 'source> {
    fn node(
        &mut self,
        node: tree_sitter::Node<'tree>,
    ) -> Result<SourceSlice<'tree, 'source>, SourceBindingError> {
        self.checked_ranges = self.checked_ranges.saturating_add(1);
        SourceSlice::from_canonical(node, self.parent.source())
    }
}
/// An extraction carrier whose selected leaf ranges have all been checked.
/// This proves readability, not CHAT validity or absence of recovery.
#[derive(Debug)]
pub struct RangeAdmittedChildren<'tree, 'source, C> {
    children: C,
    parent: SourceSlice<'tree, 'source>,
    checked_ranges: usize,
}
impl<'tree, 'source, C> RangeAdmittedChildren<'tree, 'source, C> {
    /// Borrow the immutable, range-admitted carrier.
    pub const fn children(&self) -> &C {
        &self.children
    }
    /// Source-bound parent retained without another tree lookup.
    pub const fn parent(&self) -> SourceSlice<'tree, 'source> {
        self.parent
    }
    /// Range checks performed in this transition (saturating at `usize::MAX`).
    /// Reading retained leaves performs no additional range checks.
    pub const fn checked_range_count(&self) -> usize {
        self.checked_ranges
    }
}
impl<'tree, 'source, C: AdmitRanges<'tree, 'source>> SourceChildren<'tree, 'source, C> {
    /// Admit only the selected carrier, without a CST walk or another match.
    /// Failure returns no partially admitted carrier and must be reported as an
    /// internal producer failure, never as invalid source syntax.
    /// # Errors
    /// Rejects unreadable selected ranges without returning a partial carrier.
    pub fn admit_ranges(
        self,
    ) -> Result<RangeAdmittedChildren<'tree, 'source, C::Admitted>, SourceBindingError> {
        let mut context = RangeAdmission {
            parent: self.parent,
            checked_ranges: 0,
        };
        let children = self.children.admit_ranges_in(&mut context)?;
        Ok(RangeAdmittedChildren {
            children,
            parent: self.parent,
            checked_ranges: context.checked_ranges,
        })
    }
}
