/// Every slot state preserved, with canonical source identity on node payloads.
#[derive(Debug)]
pub enum SourceSlotView<'value, 'tree, 'source, T, M, U, A> {
    /// A present value; readability is admitted by its leaf projection.
    Present(SourceField<'value, 'tree, 'source, T>),
    /// A placeholder, not valid present content.
    Missing(M),
    /// An error node, retained for recovery diagnostics.
    Error(SourceField<'value, 'tree, 'source, tree_sitter::Node<'tree>>),
    /// An unexpected node where the grammar permits this recovery state.
    Unexpected(U),
    /// No child where the grammar permits this recovery state.
    Absent(A),
}
