/// `alt_dependent_tier`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_alt_dependent_tier_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<AltDependentTierChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_alt_dependent_tier(AltDependentTierNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

