impl<'tree> Extract<'tree> for BulletNode<'tree> {
    type Children<K: KindProof> = BulletChildren<'tree>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<BulletChildren<'tree>, ReconstructionFault> {
        extract_bullet(Self(
            K::admit(evidence, self.0).map_err(ReconstructionFault::GrammarBinding)?,
        ))
    }
    fn extract_broad(self) -> Result<BulletChildren<'tree>, ReconstructionFault> {
        extract_bullet(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<BulletChildren<'tree>, ReconstructionFault> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
