/// Reconstruct the typed children of this node (spec Section 7).
/// # Errors
/// Returns a producer fault for inconsistent selected evidence, not source syntax.
pub fn extract_content_item<'tree>(
    node: ContentItemNode<'tree>,
) -> Result<ContentItemChildren<'tree>, ReconstructionFault> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    Ok({
        let content = {
            let (mut leading_extras, __at) = __cur.take_leading_extras();
            match __at.select_position(&SHAPE_106, &SHAPES_3) {
                PositionAdmission::Selected(selection) => {
                    let built = selection
                        .consume_with(|__selected, __unexpected| {
                            let (leading_extras, selected) = __selected
                                .composite_position(__unexpected)?;
                            let slot = match selected {
                                SelectedComposite::Error(node) => NodeSlot::Error(node),
                                SelectedComposite::Missing(node) => NodeSlot::Missing(node),
                                SelectedComposite::Value(__selected) => {
                                    NodeSlot::Present(
                                        ({
                                            let MatchDecision::Choice { alternative, value } = __selected
                                                .read()?
                                                .decision else {
                                                return Err(ReconstructionFault::UnexpectedDecision);
                                            };
                                            let __selected = __selected.child(value)?;
                                            match alternative {
                                                0usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        ContentItemChoice::BaseContentItem(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let (_, node) = __selected.taken_child()?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("base_content_item") => {
                                                                            BaseContentItemNode(node)
                                                                        }
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                1usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        ContentItemChoice::GroupWithAnnotations(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let (_, node) = __selected.taken_child()?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("group_with_annotations") => {
                                                                            GroupWithAnnotationsNode(node)
                                                                        }
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                2usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        ContentItemChoice::QuotationWithOptionalAnnotations(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let (_, node) = __selected.taken_child()?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind(
                                                                            "quotation_with_optional_annotations",
                                                                        ) => QuotationWithOptionalAnnotationsNode(node),
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                3usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        ContentItemChoice::IllegalCurlyQuote(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let (_, node) = __selected.taken_child()?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("illegal_curly_quote") => {
                                                                            IllegalCurlyQuoteNode(node)
                                                                        }
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                4usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        ContentItemChoice::MainPhoGroup(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let (_, node) = __selected.taken_child()?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("main_pho_group") => {
                                                                            MainPhoGroupNode(node)
                                                                        }
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                5usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        ContentItemChoice::MainSinGroup(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let (_, node) = __selected.taken_child()?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("main_sin_group") => {
                                                                            MainSinGroupNode(node)
                                                                        }
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                6usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        ContentItemChoice::CaNoBreakLinker(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let (_, node) = __selected.taken_child()?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("ca_no_break_linker") => {
                                                                            ContentItemCaNoBreakLinkerChoice::CaNoBreakLinker(
                                                                                CaNoBreakLinkerNode(node),
                                                                            )
                                                                        }
                                                                        SelectedNodeKind::Kind("ca_technical_break_linker") => {
                                                                            ContentItemCaNoBreakLinkerChoice::CaTechnicalBreakLinker(
                                                                                CaTechnicalBreakLinkerNode(node),
                                                                            )
                                                                        }
                                                                        SelectedNodeKind::Kind("linker_lazy_overlap") => {
                                                                            ContentItemCaNoBreakLinkerChoice::LinkerLazyOverlap(
                                                                                LinkerLazyOverlapNode(node),
                                                                            )
                                                                        }
                                                                        SelectedNodeKind::Kind("linker_quick_uptake") => {
                                                                            ContentItemCaNoBreakLinkerChoice::LinkerQuickUptake(
                                                                                LinkerQuickUptakeNode(node),
                                                                            )
                                                                        }
                                                                        SelectedNodeKind::Kind("linker_quick_uptake_overlap") => {
                                                                            ContentItemCaNoBreakLinkerChoice::LinkerQuickUptakeOverlap(
                                                                                LinkerQuickUptakeOverlapNode(node),
                                                                            )
                                                                        }
                                                                        SelectedNodeKind::Kind("linker_quotation_follows") => {
                                                                            ContentItemCaNoBreakLinkerChoice::LinkerQuotationFollows(
                                                                                LinkerQuotationFollowsNode(node),
                                                                            )
                                                                        }
                                                                        SelectedNodeKind::Kind("linker_self_completion") => {
                                                                            ContentItemCaNoBreakLinkerChoice::LinkerSelfCompletion(
                                                                                LinkerSelfCompletionNode(node),
                                                                            )
                                                                        }
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                _ => Err(ReconstructionFault::UnexpectedDecision),
                                            }
                                        })?,
                                    )
                                }
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                    leading_extras.extend(built.leading_extras);
                    Positioned::new(leading_extras, built.slot)
                }
                PositionAdmission::Unmatched(__at) => {
                    __at.release();
                    Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                }
            }
        };
        let Leftovers {
            trailing_extras,
            unexpected,
        } = __cur.finish();
        ContentItemChildren {
            content,
            trailing_extras,
            unexpected,
        }
    })
}
impl<'tree> Extract<'tree> for ContentItemNode<'tree> {
    type Children<K: KindProof> = ContentItemChildren<'tree>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<ContentItemChildren<'tree>, ReconstructionFault> {
        extract_content_item(Self(
            K::admit(evidence, self.0).map_err(ReconstructionFault::GrammarBinding)?,
        ))
    }
    fn extract_broad(self) -> Result<ContentItemChildren<'tree>, ReconstructionFault> {
        extract_content_item(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<ContentItemChildren<'tree>, ReconstructionFault> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct an ERROR in this rule's position without losing source identity.
    /// # Errors
    /// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
    pub fn extract_content_item_from_error_recovery(
        self,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, ContentItemChildren<'tree>>>,
        ReconstructionFault,
    > {
        self.recover_as::<ContentItemNode<'tree>, Broad>(ContentItemNode, &())
    }
    /// The same reconstruction under the admitted kind proof.
    /// # Errors
    /// Propagates language-binding or producer faults; a non-ERROR input returns `Ok(None)`.
    pub fn extract_content_item_from_error_recovery_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, ContentItemChildren<'tree>>>,
        ReconstructionFault,
    > {
        self.recover_as::<ContentItemNode<'tree>, KindAdmitted>(ContentItemNode, grammar)
    }
}
/// `content_item`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_content_item_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<ContentItemChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_content_item(ContentItemNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

