/// Reconstruct the typed children of this node (spec Section 7).
/// # Errors
/// Returns a producer fault for inconsistent selected evidence, not source syntax.
pub fn extract_contents<'tree>(
    node: ContentsNode<'tree>,
) -> Result<ContentsChildren<'tree>, ReconstructionFault> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    Ok({
        {
            let child_0 = {
                let (mut leading_extras, __at) = __cur.take_leading_extras();
                match __at.select_position(&SHAPE_111, &SHAPES_26) {
                    PositionAdmission::Selected(selection) => {
                        let built = selection
                            .consume_with(|__selected, __unexpected| {
                                let (leading_extras, selected) = __selected
                                    .composite_position(__unexpected)?;
                                let slot = match selected {
                                    SelectedComposite::Error(node) => NodeSlot::Error(node),
                                    SelectedComposite::Missing(node) => NodeSlot::Missing(node),
                                    SelectedComposite::Value(__selected) => {
                                        NodeSlot::Present(
                                            ({
                                                let MatchDecision::Choice { alternative, value } = __selected
                                                    .read()?
                                                    .decision else {
                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                };
                                                let __selected = __selected.child(value)?;
                                                match alternative {
                                                    0usize => {
                                                        Ok::<
                                                            _,
                                                            ReconstructionFault,
                                                        >(
                                                            ContentsChild0Choice::Whitespaces(
                                                                ({
                                                                    let MatchDecision::Node {
                                                                        kind,
                                                                        presence: SelectedNodePresence::Present,
                                                                    } = __selected.read()?.decision else {
                                                                        return Err(ReconstructionFault::UnexpectedDecision);
                                                                    };
                                                                    let (_, node) = __selected.taken_child()?;
                                                                    Ok::<
                                                                        _,
                                                                        ReconstructionFault,
                                                                    >(
                                                                        match kind {
                                                                            SelectedNodeKind::Kind("whitespaces") => {
                                                                                WhitespacesNode(node)
                                                                            }
                                                                            SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                                return Err(ReconstructionFault::UnexpectedDecision);
                                                                            }
                                                                        },
                                                                    )
                                                                })?,
                                                            ),
                                                        )
                                                    }
                                                    1usize => {
                                                        Ok::<
                                                            _,
                                                            ReconstructionFault,
                                                        >(
                                                            ContentsChild0Choice::ContentItem(
                                                                ({
                                                                    let MatchDecision::Node {
                                                                        kind,
                                                                        presence: SelectedNodePresence::Present,
                                                                    } = __selected.read()?.decision else {
                                                                        return Err(ReconstructionFault::UnexpectedDecision);
                                                                    };
                                                                    let (_, node) = __selected.taken_child()?;
                                                                    Ok::<
                                                                        _,
                                                                        ReconstructionFault,
                                                                    >(
                                                                        match kind {
                                                                            SelectedNodeKind::Kind("content_item") => {
                                                                                ContentItemNode(node)
                                                                            }
                                                                            SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                                return Err(ReconstructionFault::UnexpectedDecision);
                                                                            }
                                                                        },
                                                                    )
                                                                })?,
                                                            ),
                                                        )
                                                    }
                                                    2usize => {
                                                        Ok::<
                                                            _,
                                                            ReconstructionFault,
                                                        >(
                                                            ContentsChild0Choice::Separator(
                                                                ({
                                                                    let MatchDecision::Node {
                                                                        kind,
                                                                        presence: SelectedNodePresence::Present,
                                                                    } = __selected.read()?.decision else {
                                                                        return Err(ReconstructionFault::UnexpectedDecision);
                                                                    };
                                                                    let (_, node) = __selected.taken_child()?;
                                                                    Ok::<
                                                                        _,
                                                                        ReconstructionFault,
                                                                    >(
                                                                        match kind {
                                                                            SelectedNodeKind::Kind("separator") => SeparatorNode(node),
                                                                            SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                                return Err(ReconstructionFault::UnexpectedDecision);
                                                                            }
                                                                        },
                                                                    )
                                                                })?,
                                                            ),
                                                        )
                                                    }
                                                    3usize => {
                                                        Ok::<
                                                            _,
                                                            ReconstructionFault,
                                                        >(
                                                            ContentsChild0Choice::OverlapPoint(
                                                                ({
                                                                    let MatchDecision::Node {
                                                                        kind,
                                                                        presence: SelectedNodePresence::Present,
                                                                    } = __selected.read()?.decision else {
                                                                        return Err(ReconstructionFault::UnexpectedDecision);
                                                                    };
                                                                    let (_, node) = __selected.taken_child()?;
                                                                    Ok::<
                                                                        _,
                                                                        ReconstructionFault,
                                                                    >(
                                                                        match kind {
                                                                            SelectedNodeKind::Kind("overlap_point") => {
                                                                                OverlapPointNode(node)
                                                                            }
                                                                            SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                                return Err(ReconstructionFault::UnexpectedDecision);
                                                                            }
                                                                        },
                                                                    )
                                                                })?,
                                                            ),
                                                        )
                                                    }
                                                    _ => Err(ReconstructionFault::UnexpectedDecision),
                                                }
                                            })?,
                                        )
                                    }
                                };
                                Ok(Positioned::new(leading_extras, slot))
                            })?;
                        leading_extras.extend(built.leading_extras);
                        Positioned::new(leading_extras, built.slot)
                    }
                    PositionAdmission::Unmatched(__at) => {
                        __at.release();
                        Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                    }
                }
            };
            let child_1 = {
                let (leading_extras, __at) = __cur.take_leading_extras();
                let __selection = __at.select_repeat(&SHAPE_111, &SHAPES_3);
                let __items = __selection
                    .consume_with(|__selected, __unexpected| {
                        let (leading_extras, selected) = __selected
                            .composite_position(__unexpected)?;
                        let slot = match selected {
                            SelectedComposite::Error(node) => NodeSlot::Error(node),
                            SelectedComposite::Missing(node) => NodeSlot::Missing(node),
                            SelectedComposite::Value(__selected) => {
                                NodeSlot::Present(
                                    ({
                                        let MatchDecision::Choice { alternative, value } = __selected
                                            .read()?
                                            .decision else {
                                            return Err(ReconstructionFault::UnexpectedDecision);
                                        };
                                        let __selected = __selected.child(value)?;
                                        match alternative {
                                            0usize => {
                                                Ok::<
                                                    _,
                                                    ReconstructionFault,
                                                >(
                                                    ContentsChild1Choice::Whitespaces(
                                                        ({
                                                            let MatchDecision::Node {
                                                                kind,
                                                                presence: SelectedNodePresence::Present,
                                                            } = __selected.read()?.decision else {
                                                                return Err(ReconstructionFault::UnexpectedDecision);
                                                            };
                                                            let (_, node) = __selected.taken_child()?;
                                                            Ok::<
                                                                _,
                                                                ReconstructionFault,
                                                            >(
                                                                match kind {
                                                                    SelectedNodeKind::Kind("whitespaces") => {
                                                                        WhitespacesNode(node)
                                                                    }
                                                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                        return Err(ReconstructionFault::UnexpectedDecision);
                                                                    }
                                                                },
                                                            )
                                                        })?,
                                                    ),
                                                )
                                            }
                                            1usize => {
                                                Ok::<
                                                    _,
                                                    ReconstructionFault,
                                                >(
                                                    ContentsChild1Choice::ContentItem(
                                                        ({
                                                            let MatchDecision::Node {
                                                                kind,
                                                                presence: SelectedNodePresence::Present,
                                                            } = __selected.read()?.decision else {
                                                                return Err(ReconstructionFault::UnexpectedDecision);
                                                            };
                                                            let (_, node) = __selected.taken_child()?;
                                                            Ok::<
                                                                _,
                                                                ReconstructionFault,
                                                            >(
                                                                match kind {
                                                                    SelectedNodeKind::Kind("content_item") => {
                                                                        ContentItemNode(node)
                                                                    }
                                                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                        return Err(ReconstructionFault::UnexpectedDecision);
                                                                    }
                                                                },
                                                            )
                                                        })?,
                                                    ),
                                                )
                                            }
                                            2usize => {
                                                Ok::<
                                                    _,
                                                    ReconstructionFault,
                                                >(
                                                    ContentsChild1Choice::Separator(
                                                        ({
                                                            let MatchDecision::Node {
                                                                kind,
                                                                presence: SelectedNodePresence::Present,
                                                            } = __selected.read()?.decision else {
                                                                return Err(ReconstructionFault::UnexpectedDecision);
                                                            };
                                                            let (_, node) = __selected.taken_child()?;
                                                            Ok::<
                                                                _,
                                                                ReconstructionFault,
                                                            >(
                                                                match kind {
                                                                    SelectedNodeKind::Kind("separator") => SeparatorNode(node),
                                                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                        return Err(ReconstructionFault::UnexpectedDecision);
                                                                    }
                                                                },
                                                            )
                                                        })?,
                                                    ),
                                                )
                                            }
                                            3usize => {
                                                Ok::<
                                                    _,
                                                    ReconstructionFault,
                                                >(
                                                    ContentsChild1Choice::OverlapPoint(
                                                        ({
                                                            let MatchDecision::Node {
                                                                kind,
                                                                presence: SelectedNodePresence::Present,
                                                            } = __selected.read()?.decision else {
                                                                return Err(ReconstructionFault::UnexpectedDecision);
                                                            };
                                                            let (_, node) = __selected.taken_child()?;
                                                            Ok::<
                                                                _,
                                                                ReconstructionFault,
                                                            >(
                                                                match kind {
                                                                    SelectedNodeKind::Kind("overlap_point") => {
                                                                        OverlapPointNode(node)
                                                                    }
                                                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                        return Err(ReconstructionFault::UnexpectedDecision);
                                                                    }
                                                                },
                                                            )
                                                        })?,
                                                    ),
                                                )
                                            }
                                            _ => Err(ReconstructionFault::UnexpectedDecision),
                                        }
                                    })?,
                                )
                            }
                        };
                        Ok(Positioned::new(leading_extras, slot))
                    })?;
                Positioned::new(leading_extras, __items)
            };
            let Leftovers {
                trailing_extras,
                unexpected,
            } = __cur.finish();
            ContentsChildren {
                child_0,
                child_1,
                trailing_extras,
                unexpected,
            }
        }
    })
}
impl<'tree> Extract<'tree> for ContentsNode<'tree> {
    type Children<K: KindProof> = ContentsChildren<'tree>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<ContentsChildren<'tree>, ReconstructionFault> {
        extract_contents(Self(
            K::admit(evidence, self.0).map_err(ReconstructionFault::GrammarBinding)?,
        ))
    }
    fn extract_broad(self) -> Result<ContentsChildren<'tree>, ReconstructionFault> {
        extract_contents(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<ContentsChildren<'tree>, ReconstructionFault> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct an ERROR in this rule's position without losing source identity.
    /// # Errors
    /// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
    pub fn extract_contents_from_error_recovery(
        self,
    ) -> Result<Option<SourceChildren<'tree, 'source, ContentsChildren<'tree>>>, ReconstructionFault>
    {
        self.recover_as::<ContentsNode<'tree>, Broad>(ContentsNode, &())
    }
    /// The same reconstruction under the admitted kind proof.
    /// # Errors
    /// Propagates language-binding or producer faults; a non-ERROR input returns `Ok(None)`.
    pub fn extract_contents_from_error_recovery_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<Option<SourceChildren<'tree, 'source, ContentsChildren<'tree>>>, ReconstructionFault>
    {
        self.recover_as::<ContentsNode<'tree>, KindAdmitted>(ContentsNode, grammar)
    }
}
/// `contents`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_contents_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<ContentsChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_contents(ContentsNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

