/// Classify this supertype node by its own kind (spec Section 7).
#[must_use]
pub fn extract_dependent_tier<'tree>(
    node: tree_sitter::Node<'tree>,
) -> DependentTierChildren<'tree> {
    let __slot = if node.is_error() {
        NodeSlot::Error(node)
    } else if node.is_missing() {
        NodeSlot::Missing(node)
    } else {
        match DependentTierChoice::from_node(node) {
            Some(__classified) => NodeSlot::Present(__classified),
            None => NodeSlot::Unexpected(node),
        }
    };
    DependentTierChildren {
        content: Positioned::new(Vec::new(), __slot),
        trailing_extras: Vec::new(),
        unexpected: Vec::new(),
    }
}

