/// `full_document`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_full_document_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<FullDocumentChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_full_document(FullDocumentNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

