/// `id_age`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_id_age_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<IdAgeChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_id_age(IdAgeNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

