/// # Errors
/// Returns a producer fault for inconsistent selected evidence, not source syntax.
pub fn extract_id_contents<'tree>(
    node: IdContentsNode<'tree>,
) -> Result<IdContentsChildren<'tree>, ReconstructionFault> {
    node.extract_as::<Broad>(&())
}
