/// `l1_of_header`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_l1_of_header_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<L1OfHeaderChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_l1_of_header(L1OfHeaderNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

