/// `media_contents`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_media_contents_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<MediaContentsChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_media_contents(MediaContentsNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

