impl<'tree> Extract<'tree> for NonColonSeparatorNode<'tree> {
    type Children<K: KindProof> = NonColonSeparatorChildren<'tree>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<NonColonSeparatorChildren<'tree>, ReconstructionFault> {
        extract_non_colon_separator(Self(
            K::admit(evidence, self.0).map_err(ReconstructionFault::GrammarBinding)?,
        ))
    }
    fn extract_broad(self) -> Result<NonColonSeparatorChildren<'tree>, ReconstructionFault> {
        extract_non_colon_separator(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<NonColonSeparatorChildren<'tree>, ReconstructionFault> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct an ERROR in this rule's position without losing source identity.
    /// # Errors
    /// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
    pub fn extract_non_colon_separator_from_error_recovery(
        self,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, NonColonSeparatorChildren<'tree>>>,
        ReconstructionFault,
    > {
        self.recover_as::<NonColonSeparatorNode<'tree>, Broad>(NonColonSeparatorNode, &())
    }
    /// The same reconstruction under the admitted kind proof.
    /// # Errors
    /// Propagates language-binding or producer faults; a non-ERROR input returns `Ok(None)`.
    pub fn extract_non_colon_separator_from_error_recovery_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, NonColonSeparatorChildren<'tree>>>,
        ReconstructionFault,
    > {
        self.recover_as::<NonColonSeparatorNode<'tree>, KindAdmitted>(
            NonColonSeparatorNode,
            grammar,
        )
    }
}
/// `non_colon_separator`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_non_colon_separator_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<NonColonSeparatorChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_non_colon_separator(NonColonSeparatorNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

