/// Reconstruct the typed children of this node (spec Section 7).
/// # Errors
/// Returns a producer fault for inconsistent selected evidence, not source syntax.
pub fn extract_number_option<'tree>(
    node: NumberOptionNode<'tree>,
) -> Result<NumberOptionChildren<'tree>, ReconstructionFault> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    Ok({
        let content = {
            let (mut leading_extras, __at) = __cur.take_leading_extras();
            match __at.select_position(&SHAPE_423, &SHAPES_3) {
                PositionAdmission::Selected(selection) => {
                    let built = selection
                        .consume_with(|__selected, __unexpected| {
                            let (leading_extras, selected) = __selected
                                .composite_position(__unexpected)?;
                            let slot = match selected {
                                SelectedComposite::Error(node) => NodeSlot::Error(node),
                                SelectedComposite::Missing(node) => NodeSlot::Missing(node),
                                SelectedComposite::Value(__selected) => {
                                    NodeSlot::Present(
                                        ({
                                            let MatchDecision::Choice { alternative, value } = __selected
                                                .read()?
                                                .decision else {
                                                return Err(ReconstructionFault::UnexpectedDecision);
                                            };
                                            let __selected = __selected.child(value)?;
                                            match alternative {
                                                0usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        NumberOptionChoice::_1(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let (_, node) = __selected.taken_child()?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("1") => K1Node(node),
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                1usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        NumberOptionChoice::_2(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let (_, node) = __selected.taken_child()?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("2") => K2Node(node),
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                2usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        NumberOptionChoice::_3(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let (_, node) = __selected.taken_child()?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("3") => K3Node(node),
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                3usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        NumberOptionChoice::_4(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let (_, node) = __selected.taken_child()?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("4") => K4Node(node),
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                4usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        NumberOptionChoice::_5(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let (_, node) = __selected.taken_child()?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("5") => K5Node(node),
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                5usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        NumberOptionChoice::More(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let (_, node) = __selected.taken_child()?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("more") => MoreNode(node),
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                6usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        NumberOptionChoice::Audience(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let (_, node) = __selected.taken_child()?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("audience") => AudienceNode(node),
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                7usize => {
                                                    Ok::<
                                                        _,
                                                        ReconstructionFault,
                                                    >(
                                                        NumberOptionChoice::GenericNumber(
                                                            ({
                                                                let MatchDecision::Node {
                                                                    kind,
                                                                    presence: SelectedNodePresence::Present,
                                                                } = __selected.read()?.decision else {
                                                                    return Err(ReconstructionFault::UnexpectedDecision);
                                                                };
                                                                let (_, node) = __selected.taken_child()?;
                                                                Ok::<
                                                                    _,
                                                                    ReconstructionFault,
                                                                >(
                                                                    match kind {
                                                                        SelectedNodeKind::Kind("generic_number") => {
                                                                            GenericNumberNode(node)
                                                                        }
                                                                        SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                                                            return Err(ReconstructionFault::UnexpectedDecision);
                                                                        }
                                                                    },
                                                                )
                                                            })?,
                                                        ),
                                                    )
                                                }
                                                _ => Err(ReconstructionFault::UnexpectedDecision),
                                            }
                                        })?,
                                    )
                                }
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                    leading_extras.extend(built.leading_extras);
                    Positioned::new(leading_extras, built.slot)
                }
                PositionAdmission::Unmatched(__at) => {
                    __at.release();
                    Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                }
            }
        };
        let Leftovers {
            trailing_extras,
            unexpected,
        } = __cur.finish();
        NumberOptionChildren {
            content,
            trailing_extras,
            unexpected,
        }
    })
}
impl<'tree> Extract<'tree> for NumberOptionNode<'tree> {
    type Children<K: KindProof> = NumberOptionChildren<'tree>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<NumberOptionChildren<'tree>, ReconstructionFault> {
        extract_number_option(Self(
            K::admit(evidence, self.0).map_err(ReconstructionFault::GrammarBinding)?,
        ))
    }
    fn extract_broad(self) -> Result<NumberOptionChildren<'tree>, ReconstructionFault> {
        extract_number_option(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<NumberOptionChildren<'tree>, ReconstructionFault> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
