/// Reconstruct the typed children of this node (spec Section 7).
/// # Errors
/// Returns a producer fault for inconsistent selected evidence, not source syntax.
pub fn extract_para_annotation<'tree>(
    node: ParaAnnotationNode<'tree>,
) -> Result<ParaAnnotationChildren<'tree>, ReconstructionFault> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    Ok({
        {
            let child_0 = {
                let (mut leading_extras, __at) = __cur.take_leading_extras();
                match __at.select_position(&SHAPE_449, &SHAPES_6) {
                    PositionAdmission::Selected(selection) => {
                        let built = selection.consume_with(|__selected, __unexpected| {
                            let (leading_extras, leaf) = __selected.leaf_position(__unexpected)?;
                            let slot = match leaf {
                                SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                SelectedLeaf::Matched {
                                    node,
                                    kind,
                                    presence,
                                } => match kind {
                                    SelectedNodeKind::Kind("[=!") => match presence {
                                        SelectedNodePresence::Present => {
                                            NodeSlot::Present(LBrackEqBangNode(node))
                                        }
                                        SelectedNodePresence::Missing => {
                                            NodeSlot::Missing(KindMissing(LBrackEqBangNode(node)))
                                        }
                                    },
                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                        return Err(ReconstructionFault::UnexpectedDecision);
                                    }
                                },
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                        leading_extras.extend(built.leading_extras);
                        Positioned::new(leading_extras, built.slot)
                    }
                    PositionAdmission::Unmatched(__at) => {
                        __at.release();
                        Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                    }
                }
            };
            let child_1 = {
                let (mut leading_extras, __at) = __cur.take_leading_extras();
                match __at.select_position(&SHAPE_18, &SHAPES_7) {
                    PositionAdmission::Selected(selection) => {
                        let built = selection.consume_with(|__selected, __unexpected| {
                            let (leading_extras, leaf) = __selected.leaf_position(__unexpected)?;
                            let slot = match leaf {
                                SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                SelectedLeaf::Matched {
                                    node,
                                    kind,
                                    presence,
                                } => match kind {
                                    SelectedNodeKind::Kind("space") => match presence {
                                        SelectedNodePresence::Present => {
                                            NodeSlot::Present(SpaceNode(node))
                                        }
                                        SelectedNodePresence::Missing => {
                                            NodeSlot::Missing(KindMissing(SpaceNode(node)))
                                        }
                                    },
                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                        return Err(ReconstructionFault::UnexpectedDecision);
                                    }
                                },
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                        leading_extras.extend(built.leading_extras);
                        Positioned::new(leading_extras, built.slot)
                    }
                    PositionAdmission::Unmatched(__at) => {
                        __at.release();
                        Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                    }
                }
            };
            let text = {
                let (mut leading_extras, __at) = __cur.take_leading_extras();
                match __at.select_position(&SHAPE_20, &SHAPES_8) {
                    PositionAdmission::Selected(selection) => {
                        let built = selection.consume_with(|__selected, __unexpected| {
                            let (leading_extras, leaf) = __selected.leaf_position(__unexpected)?;
                            let slot = match leaf {
                                SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                SelectedLeaf::Matched {
                                    node,
                                    kind,
                                    presence,
                                } => match kind {
                                    SelectedNodeKind::Kind("annotation_content") => {
                                        match presence {
                                            SelectedNodePresence::Present => {
                                                NodeSlot::Present(AnnotationContentNode(node))
                                            }
                                            SelectedNodePresence::Missing => NodeSlot::Missing(
                                                KindMissing(AnnotationContentNode(node)),
                                            ),
                                        }
                                    }
                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                        return Err(ReconstructionFault::UnexpectedDecision);
                                    }
                                },
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                        leading_extras.extend(built.leading_extras);
                        Positioned::new(leading_extras, built.slot)
                    }
                    PositionAdmission::Unmatched(__at) => {
                        __at.release();
                        Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                    }
                }
            };
            let child_3 = {
                let (mut leading_extras, __at) = __cur.take_leading_extras();
                match __at.select_position(&SHAPE_22, &SHAPES_3) {
                    PositionAdmission::Selected(selection) => {
                        let built = selection.consume_with(|__selected, __unexpected| {
                            let (leading_extras, leaf) = __selected.leaf_position(__unexpected)?;
                            let slot = match leaf {
                                SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                SelectedLeaf::Matched {
                                    node,
                                    kind,
                                    presence,
                                } => match kind {
                                    SelectedNodeKind::Kind("right_bracket") => match presence {
                                        SelectedNodePresence::Present => {
                                            NodeSlot::Present(RightBracketNode(node))
                                        }
                                        SelectedNodePresence::Missing => {
                                            NodeSlot::Missing(KindMissing(RightBracketNode(node)))
                                        }
                                    },
                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                        return Err(ReconstructionFault::UnexpectedDecision);
                                    }
                                },
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                        leading_extras.extend(built.leading_extras);
                        Positioned::new(leading_extras, built.slot)
                    }
                    PositionAdmission::Unmatched(__at) => {
                        __at.release();
                        Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                    }
                }
            };
            let Leftovers {
                trailing_extras,
                unexpected,
            } = __cur.finish();
            ParaAnnotationChildren {
                child_0,
                child_1,
                text,
                child_3,
                trailing_extras,
                unexpected,
            }
        }
    })
}
impl<'tree> Extract<'tree> for ParaAnnotationNode<'tree> {
    type Children<K: KindProof> = ParaAnnotationChildren<'tree>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<ParaAnnotationChildren<'tree>, ReconstructionFault> {
        extract_para_annotation(Self(
            K::admit(evidence, self.0).map_err(ReconstructionFault::GrammarBinding)?,
        ))
    }
    fn extract_broad(self) -> Result<ParaAnnotationChildren<'tree>, ReconstructionFault> {
        extract_para_annotation(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<ParaAnnotationChildren<'tree>, ReconstructionFault> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct an ERROR in this rule's position without losing source identity.
    /// # Errors
    /// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
    pub fn extract_para_annotation_from_error_recovery(
        self,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, ParaAnnotationChildren<'tree>>>,
        ReconstructionFault,
    > {
        self.recover_as::<ParaAnnotationNode<'tree>, Broad>(ParaAnnotationNode, &())
    }
    /// The same reconstruction under the admitted kind proof.
    /// # Errors
    /// Propagates language-binding or producer faults; a non-ERROR input returns `Ok(None)`.
    pub fn extract_para_annotation_from_error_recovery_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, ParaAnnotationChildren<'tree>>>,
        ReconstructionFault,
    > {
        self.recover_as::<ParaAnnotationNode<'tree>, KindAdmitted>(ParaAnnotationNode, grammar)
    }
}
/// `para_annotation`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_para_annotation_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<ParaAnnotationChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_para_annotation(ParaAnnotationNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

