/// Reconstruct the typed children of this node (spec Section 7).
/// # Errors
/// Returns a producer fault for inconsistent selected evidence, not source syntax.
pub fn extract_shortening<'tree>(
    node: ShorteningNode<'tree>,
) -> Result<ShorteningChildren<'tree>, ReconstructionFault> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    Ok({
        {
            let child_0 = {
                let (mut leading_extras, __at) = __cur.take_leading_extras();
                match __at.select_position(&SHAPE_526, &SHAPES_153) {
                    PositionAdmission::Selected(selection) => {
                        let built = selection.consume_with(|__selected, __unexpected| {
                            let (leading_extras, leaf) = __selected.leaf_position(__unexpected)?;
                            let slot = match leaf {
                                SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                SelectedLeaf::Matched {
                                    node,
                                    kind,
                                    presence,
                                } => match kind {
                                    SelectedNodeKind::Kind("(") => match presence {
                                        SelectedNodePresence::Present => {
                                            NodeSlot::Present(LParenNode(node))
                                        }
                                        SelectedNodePresence::Missing => {
                                            NodeSlot::Missing(KindMissing(LParenNode(node)))
                                        }
                                    },
                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                        return Err(ReconstructionFault::UnexpectedDecision);
                                    }
                                },
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                        leading_extras.extend(built.leading_extras);
                        Positioned::new(leading_extras, built.slot)
                    }
                    PositionAdmission::Unmatched(__at) => {
                        __at.release();
                        Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                    }
                }
            };
            let child_1 = {
                let (mut leading_extras, __at) = __cur.take_leading_extras();
                match __at.select_position(&SHAPE_522, &SHAPES_154) {
                    PositionAdmission::Selected(selection) => {
                        let built = selection.consume_with(|__selected, __unexpected| {
                            let (leading_extras, leaf) = __selected.leaf_position(__unexpected)?;
                            let slot = match leaf {
                                SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                SelectedLeaf::Matched {
                                    node,
                                    kind,
                                    presence,
                                } => match kind {
                                    SelectedNodeKind::Kind("word_segment") => match presence {
                                        SelectedNodePresence::Present => {
                                            NodeSlot::Present(WordSegmentNode(node))
                                        }
                                        SelectedNodePresence::Missing => {
                                            NodeSlot::Missing(KindMissing(WordSegmentNode(node)))
                                        }
                                    },
                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                        return Err(ReconstructionFault::UnexpectedDecision);
                                    }
                                },
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                        leading_extras.extend(built.leading_extras);
                        Positioned::new(leading_extras, built.slot)
                    }
                    PositionAdmission::Unmatched(__at) => {
                        __at.release();
                        Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                    }
                }
            };
            let child_2 = {
                let (mut leading_extras, __at) = __cur.take_leading_extras();
                match __at.select_position(&SHAPE_524, &SHAPES_3) {
                    PositionAdmission::Selected(selection) => {
                        let built = selection.consume_with(|__selected, __unexpected| {
                            let (leading_extras, leaf) = __selected.leaf_position(__unexpected)?;
                            let slot = match leaf {
                                SelectedLeaf::Error(node) => NodeSlot::Error(node),
                                SelectedLeaf::Matched {
                                    node,
                                    kind,
                                    presence,
                                } => match kind {
                                    SelectedNodeKind::Kind(")") => match presence {
                                        SelectedNodePresence::Present => {
                                            NodeSlot::Present(RParenNode(node))
                                        }
                                        SelectedNodePresence::Missing => {
                                            NodeSlot::Missing(KindMissing(RParenNode(node)))
                                        }
                                    },
                                    SelectedNodeKind::Kind(_) | SelectedNodeKind::Raw => {
                                        return Err(ReconstructionFault::UnexpectedDecision);
                                    }
                                },
                            };
                            Ok(Positioned::new(leading_extras, slot))
                        })?;
                        leading_extras.extend(built.leading_extras);
                        Positioned::new(leading_extras, built.slot)
                    }
                    PositionAdmission::Unmatched(__at) => {
                        __at.release();
                        Positioned::new(leading_extras, NodeSlot::Absent(NoChild))
                    }
                }
            };
            let Leftovers {
                trailing_extras,
                unexpected,
            } = __cur.finish();
            ShorteningChildren {
                child_0,
                child_1,
                child_2,
                trailing_extras,
                unexpected,
            }
        }
    })
}
impl<'tree> Extract<'tree> for ShorteningNode<'tree> {
    type Children<K: KindProof> = ShorteningChildren<'tree>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<ShorteningChildren<'tree>, ReconstructionFault> {
        extract_shortening(Self(
            K::admit(evidence, self.0).map_err(ReconstructionFault::GrammarBinding)?,
        ))
    }
    fn extract_broad(self) -> Result<ShorteningChildren<'tree>, ReconstructionFault> {
        extract_shortening(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<ShorteningChildren<'tree>, ReconstructionFault> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct an ERROR in this rule's position without losing source identity.
    /// # Errors
    /// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
    pub fn extract_shortening_from_error_recovery(
        self,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, ShorteningChildren<'tree>>>,
        ReconstructionFault,
    > {
        self.recover_as::<ShorteningNode<'tree>, Broad>(ShorteningNode, &())
    }
    /// The same reconstruction under the admitted kind proof.
    /// # Errors
    /// Propagates language-binding or producer faults; a non-ERROR input returns `Ok(None)`.
    pub fn extract_shortening_from_error_recovery_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, ShorteningChildren<'tree>>>,
        ReconstructionFault,
    > {
        self.recover_as::<ShorteningNode<'tree>, KindAdmitted>(ShorteningNode, grammar)
    }
}
/// `shortening`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_shortening_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<ShorteningChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_shortening(ShorteningNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

