impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct an ERROR in this rule's position without losing source identity.
    /// # Errors
    /// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
    pub fn extract_situation_header_from_error_recovery(
        self,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, SituationHeaderChildren<'tree>>>,
        ReconstructionFault,
    > {
        self.recover_as::<SituationHeaderNode<'tree>, Broad>(SituationHeaderNode, &())
    }
    /// The same reconstruction under the admitted kind proof.
    /// # Errors
    /// Propagates language-binding or producer faults; a non-ERROR input returns `Ok(None)`.
    pub fn extract_situation_header_from_error_recovery_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, SituationHeaderChildren<'tree, KindAdmitted>>>,
        ReconstructionFault,
    > {
        self.recover_as::<SituationHeaderNode<'tree>, KindAdmitted>(SituationHeaderNode, grammar)
    }
}
/// `situation_header`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_situation_header_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<SituationHeaderChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_situation_header(SituationHeaderNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

