impl<'tree> Extract<'tree> for WordBodyNode<'tree> {
    type Children<K: KindProof> = WordBodyChildren<'tree>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<WordBodyChildren<'tree>, ReconstructionFault> {
        extract_word_body(Self(
            K::admit(evidence, self.0).map_err(ReconstructionFault::GrammarBinding)?,
        ))
    }
    fn extract_broad(self) -> Result<WordBodyChildren<'tree>, ReconstructionFault> {
        extract_word_body(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<WordBodyChildren<'tree>, ReconstructionFault> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct an ERROR in this rule's position without losing source identity.
    /// # Errors
    /// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
    pub fn extract_word_body_from_error_recovery(
        self,
    ) -> Result<Option<SourceChildren<'tree, 'source, WordBodyChildren<'tree>>>, ReconstructionFault>
    {
        self.recover_as::<WordBodyNode<'tree>, Broad>(WordBodyNode, &())
    }
    /// The same reconstruction under the admitted kind proof.
    /// # Errors
    /// Propagates language-binding or producer faults; a non-ERROR input returns `Ok(None)`.
    pub fn extract_word_body_from_error_recovery_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<Option<SourceChildren<'tree, 'source, WordBodyChildren<'tree>>>, ReconstructionFault>
    {
        self.recover_as::<WordBodyNode<'tree>, KindAdmitted>(WordBodyNode, grammar)
    }
}
/// `word_body`'s children from the ERROR standing in for one; see the module header.
/// # Errors
/// Propagates producer faults; a non-ERROR input instead returns `Ok(None)`.
pub fn extract_word_body_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Result<Option<WordBodyChildren<'tree>>, ReconstructionFault> {
    if node.is_error() {
        extract_word_body(WordBodyNode(node)).map(Some)
    } else {
        Ok(None)
    }
}

